-- Lua 5.1/OpenResty-compatible bounded request WAF engine.
-- The snapshot is generated by Python as a Lua table, not parsed from JSON.
local M = {}
local snapshot = { version = 0, sites = {} }
local snapshot_path = "/www/server/nginx_guard/runtime/snapshot.lua"
local version_path = "/www/server/nginx_guard/runtime/version"
local BODY_MAX_BYTES = 1048576

local FALLBACK_PATTERNS = {
    sensitive = [[(?:^|/)(?:\.env(?:\.[A-Za-z0-9_.-]+)?|\.git(?:/.*)?|\.git-credentials|\.aws(?:/.*)?|\.azure(?:/.*)?|\.vscode(?:/.*)?|wp-config\.php(?:\.(?:bak|old|swp)|~)?|terraform\.tfstate|docker-compose\.ya?ml|serverless\.ya?ml|application\.ya?ml|config\.json)(?:[/?]|$)]],
    traversal = [[(?:\.\./|/etc/(?:passwd|shadow)|/proc/(?:self|1)/(?:environ|cmdline))]],
    metadata = [[(?:169\.254\.169\.254|metadata\.google\.internal|latest/meta-data|latest/user-data)]],
    sqli = [[(?:\bunion(?:\s|%20|\+)+select\b|\bor(?:\s|%20|\+)+1(?:\s|%20|\+)*(?:=|%3d)(?:\s|%20|\+)*1\b|\bsleep(?:\s|%20|\+)*\(|\bsleep(?:\s|%20|\+)*%28|information(?:_|%5f)schema)]],
    xss = [[(?:<script\b|%3cscript\b|javascript(?::|%3a)|on(?:error|load)(?:\s|%20|\+)*(?:=|%3d))]],
    scanner = [[(?:sqlmap|nikto|nmap|masscan|zgrab|wpscan)]],
}

local DEFAULT_RULES = {
    NG1001 = { name = "敏感文件暴露", action = "block", high_risk = true },
    NG1002 = { name = "路径穿越", action = "block", high_risk = true },
    NG1003 = { name = "云元数据 SSRF", action = "block", high_risk = true },
    NG2001 = { name = "SQL 注入特征", action = "block", high_risk = false },
    NG2002 = { name = "XSS 特征", action = "block", high_risk = false },
    NG2003 = { name = "扫描器 User-Agent", action = "block", high_risk = false },
}

local function decode(value)
    local text = tostring(value or "")
    for _ = 1, 2 do
        local decoded = text:gsub("%%(%x%x)", function(hex)
            return string.char(tonumber(hex, 16))
        end)
        if decoded == text then
            break
        end
        text = decoded
    end
    return text:gsub("\\", "/")
end

local function load_snapshot()
    local ok, value = pcall(dofile, snapshot_path)
    if ok and type(value) == "table" then
        snapshot = value
        return true
    end
    return false
end

local function current_version()
    local ok, value = pcall(dofile, version_path)
    if ok and type(value) == "number" then
        return value
    end
    return snapshot.version or 0
end

function M.reload()
    load_snapshot()
end

function M.reload_if_changed()
    if current_version() ~= (snapshot.version or 0) then
        load_snapshot()
    end
end

local function find_pattern(value, pattern)
    if not pattern or pattern == "" then
        return false
    end
    local ok, from = pcall(ngx.re.find, tostring(value or ""), tostring(pattern), "ijo")
    return ok and from ~= nil
end

local function patterns()
    local configured = snapshot.patterns or {}
    local result = {}
    for name, fallback in pairs(FALLBACK_PATTERNS) do
        result[name] = configured[name] or fallback
    end
    return result
end

local function contains(text, needle)
    return string.find(string.lower(text or ""), needle, 1, true) ~= nil
end

local function high_risk(path, args)
    local current = patterns()
    local decoded_path = decode(path)
    local decoded_args = decode(args)
    local value = decoded_path .. "?" .. decoded_args
    if find_pattern(decoded_path, current.sensitive) or find_pattern(value, current.sensitive) then
        return "NG1001"
    end
    if find_pattern(value, current.traversal)
        or contains(value, "../")
        or contains(value, "/etc/passwd")
        or contains(value, "/etc/shadow")
        or contains(value, "/proc/self/environ")
        or contains(value, "/proc/1/environ") then
        return "NG1002"
    end
    if find_pattern(decoded_args, current.metadata)
        or find_pattern(value, current.metadata)
        or contains(value, "169.254.169.254")
        or contains(value, "metadata.google.internal")
        or contains(value, "latest/meta-data") then
        return "NG1003"
    end
    return nil
end

local function builtin_rule(site, rule_id)
    local configured = site.builtin_rules and site.builtin_rules[rule_id]
    if type(configured) == "table" then
        return configured
    end
    local override = site.rule_overrides and site.rule_overrides[rule_id]
    local fallback = DEFAULT_RULES[rule_id]
    if type(override) == "table" then
        return {
            name = fallback and fallback.name or rule_id,
            enabled = override.enabled ~= false,
            action = tostring(override.action or (fallback and fallback.action or "block")):lower(),
            high_risk = fallback and fallback.high_risk or false,
        }
    end
    return fallback or { name = rule_id, enabled = true, action = "block", high_risk = false }
end

local function interface_matches(site, host, port, uri)
    local request_host = string.lower(tostring(host or "")):gsub("%.$", "")
    local request_port = tonumber(port)
    local request_path = tostring(uri or "/"):gsub("%?.*$", "")
    if request_path == "" then
        request_path = "/"
    end
    for _, entry in ipairs(site.interface_whitelist or {}) do
        if type(entry) == "table" then
            local entry_host = string.lower(tostring(entry.host or "")):gsub("%.$", "")
            local expected_port = entry.port and tonumber(entry.port) or nil
            if entry_host ~= "" and entry_host == request_host
                and (expected_port == nil or expected_port == request_port) then
                local path = tostring(entry.path or "/")
                if entry.whole_host or (tostring(entry.match) == "prefix" and path == "/") then
                    return true
                end
                if tostring(entry.match) == "exact" and request_path == path then
                    return true
                end
                if tostring(entry.match) == "prefix" then
                    local boundary = path
                    if string.sub(boundary, -1) ~= "/" then
                        boundary = boundary .. "/"
                    end
                    if request_path == path or string.sub(request_path, 1, #boundary) == boundary then
                        return true
                    end
                end
            end
        end
    end
    return false
end

local function custom_match(rule, uri, args)
    local match = tostring(rule.match or "")
    local pattern = tostring(rule.pattern or "")
    local value = uri
    if match == "query_contains" then
        value = args
    elseif match == "host" then
        value = ngx.var.host or ""
    elseif match == "user_agent" then
        value = ngx.var.http_user_agent or ""
    elseif match == "header" then
        local header_ok, header_value = pcall(function()
            return ngx.var["http_" .. string.lower(tostring(rule.header or ""))]
        end)
        value = header_ok and (header_value or "") or ""
    elseif match == "method" then
        value = ngx.var.request_method or ""
    elseif match == "ip" then
        value = ngx.var.remote_addr or ""
    end
    if match == "uri_regex" then
        return find_pattern(value, pattern)
    end
    return string.find(string.lower(value or ""), string.lower(pattern), 1, true) ~= nil
end

local function attack_decision(site, rule_id, status, ip)
    if tostring(site.mode) ~= "BLOCK" then
        return nil
    end
    local ban = ngx.shared.ng_guard_ban
    local site_id = tostring(ngx.var.ng_guard_site_id or "")
    local ban_key = "ban:" .. site_id .. ":" .. ip
    if ban and ban:get(ban_key) then
        return { action = "block", status = 403, rule_id = "NG3002", rule_name = "临时 IP 封禁" }
    end
    local config = site.auto_ban or {}
    if ban and config.enabled ~= false then
        local counter = ngx.shared.ng_guard_cc
        local window = tonumber(config.window) or 10
        local threshold = tonumber(config.threshold) or 20
        local count, err = counter:incr("attack:" .. site_id .. ":" .. ip, 1, 0, window)
        if not err and count and count >= threshold then
            ban:set(ban_key, true, tonumber(config.duration) or 600)
            return { action = "block", status = 403, rule_id = "NG3002", rule_name = "临时 IP 封禁" }
        end
    end
    return { action = "block", status = status, rule_id = rule_id }
end

local function builtin_decision(site, rule_id, ip)
    local rule = builtin_rule(site, rule_id)
    if not rule or rule.enabled == false then
        return nil
    end
    local action = tostring(rule.action or "block"):lower()
    local blocking = action == "block" or action == "deny"
        or action == "403" or action == "404" or action == "429" or action == "444"
    local status = 403
    if action == "404" or action == "429" or action == "444" then
        status = tonumber(action)
    end
    if blocking and tostring(site.mode) == "BLOCK" then
        return attack_decision(site, rule_id, status, ip)
    end
    return {
        action = "monitor",
        status = 200,
        rule_id = rule_id,
        rule_name = rule.name or rule_id,
    }
end

local function body_content_type()
    local value = tostring(ngx.var.http_content_type or "")
    return string.lower((value:match("^[^;]*") or ""):gsub("^%s+", ""):gsub("%s+$", ""))
end

local function text_content_type(content_type)
    return string.sub(content_type, 1, 5) == "text/"
        or content_type == "application/json"
        or content_type == "application/x-www-form-urlencoded"
        or content_type == "application/xml"
        or string.sub(content_type, -5) == "+json"
        or string.sub(content_type, -4) == "+xml"
end

local function body_rule(site, ip)
    local settings = site.body_inspection or {}
    if settings.enabled == false or settings.text_only == false then
        return nil
    end
    local method = string.upper(tostring(ngx.var.request_method or "GET"))
    if method == "GET" or method == "HEAD" then
        return nil
    end
    if tostring(ngx.var.http_upgrade or "") ~= "" then
        return nil
    end
    if tostring(ngx.var.http_content_encoding or "") ~= "" then
        return nil
    end
    local content_type = body_content_type()
    if not text_content_type(content_type) then
        return nil
    end
    local max_bytes = tonumber(settings.max_bytes) or BODY_MAX_BYTES
    if max_bytes <= 0 or max_bytes > BODY_MAX_BYTES then
        max_bytes = BODY_MAX_BYTES
    end
    local declared_length = tonumber(ngx.var.http_content_length or "")
    -- Without Content-Length (for example chunked transfer), access phase
    -- cannot prove the body is bounded before read_body; skip inspection.
    if not declared_length or declared_length < 0 or declared_length > max_bytes then
        return nil
    end
    local read_ok = pcall(ngx.req.read_body)
    if not read_ok then
        return nil
    end
    local data = ngx.req.get_body_data()
    if not data or #data == 0 or #data > max_bytes then
        return nil
    end
    local current = patterns()
    local rule_id = nil
    if find_pattern(data, current.sqli) then
        rule_id = "NG2001"
    elseif find_pattern(data, current.xss) then
        rule_id = "NG2002"
    end
    if rule_id then
        return builtin_decision(site, rule_id, ip)
    end
    return nil
end

function M.inspect()
    local site_id = tostring(ngx.var.ng_guard_site_id or "")
    local site = snapshot.sites[site_id]
    if not site or tostring(site.mode or "OFF") == "OFF" then
        return { action = "allow", status = 200 }
    end

    local uri = ngx.var.uri or ngx.var.request_uri or ""
    local args = ngx.var.args or ""
    local ip = ngx.var.remote_addr or ""
    local host = ngx.var.host or ""
    local port = ngx.var.server_port or ""
    local ip_whitelisted = site.whitelist and site.whitelist[ip]
    local native_whitelist_ok, native_whitelist = pcall(function()
        return ngx.var["ng_guard_whitelist_" .. site_id]
    end)
    if native_whitelist_ok and native_whitelist == "1" then
        ip_whitelisted = true
    end
    local interface_whitelisted = interface_matches(site, host, port, uri)
    local ordinary_whitelisted = ip_whitelisted or interface_whitelisted

    local ban = ngx.shared.ng_guard_ban
    if tostring(site.mode) == "BLOCK" and ban and ban:get("ban:" .. site_id .. ":" .. ip) then
        return { action = "block", status = 403, rule_id = "NG3002", rule_name = "临时 IP 封禁" }
    end

    -- Native maps perform the cheap URI/query/User-Agent match before this
    -- access phase.  When Lua is available, consume that result here so all
    -- built-in hits share the same temporary-ban accounting as body hits.
    local native_rule_ok, native_rule = pcall(function()
        return ngx.var["ng_guard_site_log_rule_id_" .. site_id]
    end)
    if native_rule_ok and native_rule and native_rule ~= "" then
        local decision = builtin_decision(site, native_rule, ip)
        if decision then
            return decision
        end
    end

    local rule_id = high_risk(uri, args)
    if rule_id then
        -- Interface/IP whitelists bypass ordinary controls only. These three
        -- high-risk rules are deliberately evaluated first and never skipped.
        local decision = builtin_decision(site, rule_id, ip)
        if decision then
            return decision
        end
    end

    if not ordinary_whitelisted then
        local current = patterns()
        local combined = decode(uri) .. "?" .. decode(args)
        local request_rule = nil
        if find_pattern(combined, current.sqli) then
            request_rule = "NG2001"
        elseif find_pattern(combined, current.xss) then
            request_rule = "NG2002"
        elseif find_pattern(ngx.var.http_user_agent or "", current.scanner) then
            request_rule = "NG2003"
        end
        if request_rule then
            local decision = builtin_decision(site, request_rule, ip)
            if decision then
                return decision
            end
        end

        for _, rule in ipairs(site.custom_rules or {}) do
            if rule.enabled ~= false and custom_match(rule, uri, args) then
                local action = tostring(rule.action or "monitor"):lower()
                if action ~= "allow" then
                    local status = 403
                    if action == "404" or action == "429" or action == "444" then
                        status = tonumber(action)
                    end
                    if action == "block" or action == "403" or action == "404"
                        or action == "429" or action == "444" then
                        if tostring(site.mode) == "BLOCK" then
                            return attack_decision(site, rule.id or "CUSTOM", status, ip)
                        end
                    end
                    return {
                        action = "monitor",
                        status = 200,
                        rule_id = rule.id or "CUSTOM",
                        rule_name = rule.name or "自定义规则",
                    }
                end
            end
        end

        local body_decision = body_rule(site, ip)
        if body_decision then
            return body_decision
        end
    end

    -- Primary CC is limit_req in generated Native config.  Keeping this
    -- engine free of a second request counter avoids duplicate throttling and
    -- the historical 503/429 mismatch.
    return { action = "allow", status = 200 }
end

return M
